-- Backup portal_berita 2026-09-14 08:00:47

DROP TABLE IF EXISTS `admin_logs`;
CREATE TABLE `admin_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `admin_id` int DEFAULT NULL,
  `action` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `details` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `admin_users`;
CREATE TABLE `admin_users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) NOT NULL,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `berita`;
CREATE TABLE `berita` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kategori_id` int unsigned NOT NULL DEFAULT '0',
  `judul` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `ringkasan` text,
  `isi` longtext NOT NULL,
  `penulis` varchar(100) DEFAULT NULL,
  `status` enum('draft','publish') NOT NULL DEFAULT 'draft',
  `tanggal_publikasi` datetime DEFAULT NULL,
  `gambar` varchar(255) DEFAULT NULL,
  `views` int unsigned NOT NULL DEFAULT '0',
  `show_meta` tinyint(1) NOT NULL DEFAULT '1',
  `show_ringkasan` tinyint(1) NOT NULL DEFAULT '1',
  `show_penulis` tinyint(1) NOT NULL DEFAULT '1',
  `show_tanggal` tinyint(1) NOT NULL DEFAULT '1',
  `show_kategori` tinyint(1) NOT NULL DEFAULT '1',
  `show_gambar_detail` tinyint(1) NOT NULL DEFAULT '1',
  `layout_style` enum('default','wide','boxed') NOT NULL DEFAULT 'default',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_berita_kategori` (`kategori_id`),
  CONSTRAINT `fk_berita_kategori` FOREIGN KEY (`kategori_id`) REFERENCES `kategori` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `kategori`;
CREATE TABLE `kategori` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) NOT NULL,
  `slug` varchar(150) NOT NULL,
  `grid_count` int NOT NULL DEFAULT '12',
  `grid_style` varchar(20) NOT NULL DEFAULT 'grid',
  `animasi` varchar(30) NOT NULL DEFAULT 'fade-up',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `komentar`;
CREATE TABLE `komentar` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `berita_id` int unsigned NOT NULL,
  `nama` varchar(100) NOT NULL,
  `email` varchar(150) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `isi` text NOT NULL,
  `status` enum('pending','approved','spam') NOT NULL DEFAULT 'pending',
  `ip_hash` char(64) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_komentar_berita` (`berita_id`),
  KEY `idx_komentar_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `login_attempts`;
CREATE TABLE `login_attempts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ip` varchar(45) NOT NULL,
  `attempted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_login_attempts_ip` (`ip`),
  KEY `idx_login_attempts_time` (`attempted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `menus`;
CREATE TABLE `menus` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) NOT NULL,
  `slug` varchar(150) NOT NULL,
  `urutan` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `parent_id` int unsigned NOT NULL DEFAULT '0',
  `menu_type` enum('link','dropdown','mega') NOT NULL DEFAULT 'link',
  `kategori_id` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `newsletter_history`;
CREATE TABLE `newsletter_history` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `subject` varchar(255) NOT NULL,
  `content` longtext NOT NULL,
  `recipients_count` int unsigned DEFAULT '0',
  `sent_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `sent_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `newsletter_subscribers`;
CREATE TABLE `newsletter_subscribers` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(190) NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `sections`;
CREATE TABLE `sections` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `area` enum('home','footer','sidebar') NOT NULL DEFAULT 'home',
  `tipe` varchar(40) NOT NULL DEFAULT 'latest',
  `judul` varchar(200) DEFAULT NULL,
  `pengaturan` text,
  `animasi` varchar(30) NOT NULL DEFAULT 'fade-up',
  `urutan` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sections_area` (`area`,`urutan`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `site_name` varchar(150) NOT NULL,
  `site_tagline` varchar(255) DEFAULT NULL,
  `logo_path` varchar(255) DEFAULT NULL,
  `favicon_path` varchar(255) DEFAULT NULL,
  `latest_news_count` int NOT NULL DEFAULT '5',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `footer_email` varchar(255) DEFAULT NULL,
  `footer_address` text,
  `footer_phone` varchar(50) DEFAULT NULL,
  `footer_social_facebook` varchar(255) DEFAULT NULL,
  `footer_social_twitter` varchar(255) DEFAULT NULL,
  `footer_social_instagram` varchar(255) DEFAULT NULL,
  `komentar_aktif` tinyint(1) NOT NULL DEFAULT '1',
  `komentar_moderasi` tinyint(1) NOT NULL DEFAULT '1',
  `komentar_captcha` tinyint(1) NOT NULL DEFAULT '1',
  `komentar_max_links` tinyint NOT NULL DEFAULT '2',
  `komentar_interval_detik` int NOT NULL DEFAULT '30',
  `komentar_kata_kasar` text,
  `theme_id` varchar(50) NOT NULL DEFAULT 'indigo',
  `theme_color_id` varchar(50) NOT NULL DEFAULT 'purple',
  `footer_admin_link_url` varchar(255) DEFAULT '/admin/login',
  `footer_admin_link_title` varchar(255) DEFAULT 'Login Admin',
  `footer_admin_link_show` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `visitor_logs`;
CREATE TABLE `visitor_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ip_hash` char(64) NOT NULL,
  `user_agent` text,
  `os` varchar(80) NOT NULL DEFAULT 'Tidak diketahui',
  `country` varchar(100) NOT NULL DEFAULT 'Tidak diketahui',
  `page_type` varchar(40) NOT NULL DEFAULT 'page',
  `page_url` varchar(500) DEFAULT NULL,
  `kategori_id` int unsigned DEFAULT NULL,
  `berita_id` int unsigned DEFAULT NULL,
  `referer` varchar(500) DEFAULT NULL,
  `visited_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_visitor_logs_visited_at` (`visited_at`),
  KEY `idx_visitor_logs_kategori` (`kategori_id`),
  KEY `idx_visitor_logs_berita` (`berita_id`),
  KEY `idx_visitor_logs_os` (`os`),
  KEY `idx_visitor_logs_country` (`country`)
) ENGINE=InnoDB AUTO_INCREMENT=330 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


